import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as a,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"上下文工程（怎么往窗口里塞）","description":"窗口是预算。本页只写往里塞什么、丢掉什么。机制见 Learn LLM 第 15 章。","frontmatter":{"title":"上下文工程（怎么往窗口里塞）","description":"窗口是预算。本页只写往里塞什么、丢掉什么。机制见 Learn LLM 第 15 章。","domain":"tech","tags":["fundamentals"],"llm":[15,11]},"headers":[],"relativePath":"zh/tech/fundamentals/context-engineering.md","filePath":"zh/tech/fundamentals/context-engineering.md","lastUpdated":1788250975000}'),o={name:"zh/tech/fundamentals/context-engineering.md"};function d(l,t,i,h,s,c){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="上下文工程-怎么往窗口里塞" tabindex="-1">上下文工程（怎么往窗口里塞） <a class="header-anchor" href="#上下文工程-怎么往窗口里塞" aria-label="Permalink to &quot;上下文工程（怎么往窗口里塞）&quot;">​</a></h1><p><strong>结论</strong>：提示写清之后，质量差往往是窗口里塞错了东西。系统提示、工具定义、检索片段、聊天记录抢同一份 token。</p><blockquote><p><strong>概念。</strong> Prompt 是规则怎么写；上下文工程是这一轮窗口里留什么。记忆四模式、按 tool-unit 截断见 Learn LLM <a href="https://llm.zenheart.site/chapters/15-prompt-memory" target="_blank" rel="noreferrer">第 15 章 A5</a>。完整「预算 / 压缩 / 多轮状态」实验见 <a href="https://github.com/zenHeart/learn-llm/issues/1" target="_blank" rel="noreferrer">learn-llm#1</a>。</p><p>官方工程笔记：<a href="https://www.anthropic.com/engineering/effective-context-engineering-for-ai-agents" target="_blank" rel="noreferrer">Effective context engineering for AI agents</a>。</p></blockquote><h2 id="工程上你要做的三件事" tabindex="-1">工程上你要做的三件事 <a class="header-anchor" href="#工程上你要做的三件事" aria-label="Permalink to &quot;工程上你要做的三件事&quot;">​</a></h2><ol><li><strong>稳定前缀放前面。</strong> 系统提示、工具 schema、few-shot 尽量不改，才能吃到 prompt cache。每轮变化的用户输入和检索结果放后面。</li><li><strong>不要一次挂上所有 MCP 工具。</strong> 五个服务器的工具定义就能吃掉数万 token。只开这一任务用得上的；其余按需发现。</li><li><strong>超窗先裁工具配对，再裁旧闲聊。</strong> 直接 <code>messages.slice(-N)</code> 会切断 tool call / tool result，下一轮请求直接 400。实现细节回第 15 章。</li></ol><h2 id="编码助手里" tabindex="-1">编码助手里 <a class="header-anchor" href="#编码助手里" aria-label="Permalink to &quot;编码助手里&quot;">​</a></h2><table tabindex="0"><thead><tr><th>要做</th><th>不要做</th></tr></thead><tbody><tr><td><code>@</code> 点名文件，而不是「看看整个仓库」</td><td>把整份设计文档贴进每一轮</td></tr><tr><td>长文放上面，问题放下面；先引用再改</td><td>把 AGENTS.md 写成第二份百科</td></tr><tr><td>用检索 / grep，而不是把日志全贴进去</td><td>同时开十个 MCP 服务器「以备不时之需」</td></tr></tbody></table><h2 id="产品里" tabindex="-1">产品里 <a class="header-anchor" href="#产品里" aria-label="Permalink to &quot;产品里&quot;">​</a></h2><table tabindex="0"><thead><tr><th>要做</th><th>不要做</th></tr></thead><tbody><tr><td>检索只回 top-k，并带来源</td><td>把向量库全表拼进 prompt</td></tr><tr><td>系统提示当代码版本化</td><td>把用户原文和规则揉在一段</td></tr><tr><td>超窗用明确策略（裁 / 摘要 / 记忆检索）</td><td>静默丢最前面的系统提示</td></tr></tbody></table><p>接到检索 → <a href="/zh/tech/patterns/RAG.html">RAG</a>。接到助手规矩 → <a href="/zh/tech/prompt/agents-doc.html">AGENTS.md</a>。</p>',10)])])}const _=e(o,[["render",d]]);export{b as __pageData,_ as default};
